insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'full', 'Yes (unit of ZTA)', 'Yes', 'No', 4, 1, 4500, null, false, 'green', 'FCDO: no areas advised against; caution on demonstrations, cash/card difficulties, power cuts', 'Zimbabwe National Convention Bureau (ZNCB), a unit of Zimbabwe Tourism Authority under Ministry of Tourism & Hospitality Industry; set up 2013/14; zimbabwetourism.net', 'Harare International Conference Centre (HICC, Rainbow Towers), Harare: 4,500 seats; ~10,000 sqm indoor exhibition; Rainbow Towers 304 rooms', 'Category A visa-free (SADC etc.), Category B visa on arrival (most EU/US/UK/Commonwealth), Category C prior visa; fee USD 55 cash; e-visa at evisa.gov.zw; KAZA UniVisa USD 50', '2026-11-04' from public.countries where name = 'Zimbabwe' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'full', 'No', 'Informal', 'No', 5, 2, 2500, null, false, 'green', 'FCDO: no areas advised against; caution near DRC border rural areas', 'No convention bureau. Zambia Tourism Agency (ZTA; Ministry of Tourism; Tourism & Hospitality Act 2015) handles MICE marketing; new board May 2026', 'Kenneth Kaunda International Conference Centre (KKICC), Lusaka: 2,500+ auditorium, 15 conference rooms, commissioned 2022; exhibition sqm not published', '167 countries visa-free from 1 Jan 2025 (all SADC, EU, UK, US, Gulf, China, India); 34 VOA; 51 prior visa; single-entry USD 25; e-visa; KAZA UniVisa USD 50; VOA facilitated for conference delegates on request', '2026-11-04' from public.countries where name = 'Zambia' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'full', 'Yes (Jan 2026)', 'Yes', 'Proposed (draft NTS)', 4, 20, 4000, 29, true, 'green', 'FCDO: all travel advised against in Mandera, parts of Wajir, Garissa, Lamu (excl. islands); all but essential to parts of coast. Nairobi/Mombasa no advisory', 'Kenya National Convention Bureau (KNCB); Ministry of Tourism & Wildlife; first launched Oct 2019, dissolved c.2020; re-approved by Cabinet 15 Dec 2025, launched Jan 2026; parent agency and website not confirmed', 'KICC, Nairobi: Tsavo Hall 4,000 (2,444 sqm); hosted 20,000 delegates at Africa Climate Summit 2023. Bomas International Convention Complex, 11,000 delegates, due 2026 (40% complete Jan 2026)', 'Universal eTA since Jan 2024 (pre-arrival, ~3 days, up to 90 days, no VOA); from 2025 all African and Caribbean nationals exempt from eTA and fees (except Libya, Somalia); EAC citizens 6 months', '2026-11-04' from public.countries where name = 'Kenya' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'Informal', 'No', 3, 14, null, 9, true, 'green', 'Lagos: no formal advisory, "be cautious", esp. mainland. Abuja/FCT: no formal advisory, "be cautious"; UK staff restricted to Abuja metro area. Advice against all travel to Borno, Yobe, Adamawa, Gombe, Katsina, Zamfara, Sokoto, riverine Niger Delta; against all but essential travel to 16 further states. Updated 28 Oct 2026', 'None. No national convention bureau; bids are fragmented private/ministry efforts (Oct 2025 analysis proposes a "National Strategic Events and Conferences Office")', 'Eko Convention Centre, Lagos (Eko Hotels): 3,000 conference/banquet, 6,000 concert; 5,151 sqm main hall divisible into 5; 270 booths; 13 meeting rooms. Theatre capacity: unverified (commonly cited ~5,000+). Also Bola Ahmed Tinubu Intl Conference Centre, Abuja (ex-Abuja ICC) reopened 10 Jun 2025 after renovation; capacities not published', 'ECOWAS visa-free; e-Visa for 177 nationalities from 1 May 2025 (policy live 8 May 2025); Visa-on-Arrival abolished 1 May 2025; 25 nationalities must apply at missions; no conference-visa category; stated processing 48h (metadata) vs 10 working days (body). Ease score: 3', '2026-11-04' from public.countries where name = 'Nigeria' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'Informal', 'No', 4, 10, 1600, 12, true, 'green', 'Accra: no advisory. Only Bawku Municipality (Upper East) under "all but essential". Updated 2 Jul 2026', 'None formal. Ghana Tourism Authority (GTA, under Ministry of Tourism) and Ghana Tourism Development Company (GTDC) both act as MICE promoters; GTDC named MICE a "strategic growth pillar" (May 2026); no bureau named', 'Accra International Conference Centre (AICC), Accra: 1,600 (infobox, whole centre; main hall commonly cited ~1,600 theatre); opened 1991; structural concerns, refurbishment ordered Feb 2026 and a new PPP convention centre planned to start 2026. Exhibition sqm: unverified', 'ECOWAS visa-free; from 25 May 2026 free e-visa (fee waived, not visa-free) for ALL African passport holders; e-visa platform for others; existing bilateral visa-free (e.g. Zimbabwe). Ease score: 4', '2026-11-04' from public.countries where name = 'Ghana' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'Informal', 'No', 3, 18, 1500, 6, false, 'green', 'Dakar/Diamniadio: no advisory. Caution in northern/eastern border areas (Mali/Mauritania) and Casamance. Updated 15 Oct 2026', 'None yet. ASPT (Agence sénégalaise de promotion touristique, Ministry of Culture, Crafts & Tourism) launched a MICE consultation framework 11 Aug 2026 intended to lead to a "Bureau de Convention"; partnership with Diamniadio urban-pole delegation', 'Centre International de Conférences Abdou Diouf (CICAD), Diamniadio (opened 2014, cost FCFA 51.1bn): plenary capacity commonly cited 1,500 but not verified on an official page; modular halls + exhibition space (sqm unverified). Secondary: King Fahd Palace Dakar — 6,000 sqm centre, 700-seat amphitheatre, 66 rooms; CICES Dakar (exhibition fairground)', 'Visa-free 90 days for ECOWAS + published list of 29 African countries (incl. Kenya, Rwanda, South Africa, Uganda, Morocco); VOA at Dakar airport for listed nationalities; reciprocity-based e-visa with online fee announced Aug 2025 for non-African nationals whose countries require visas of Senegalese (France, US, UK, Canada, China expected) — start date/fee unpublished. Ease score: 3 (4 for Africans)', '2026-11-04' from public.countries where name = 'Senegal' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'Yes', 'No', 3, 9, 5000, null, false, 'green', 'Abidjan/Yamoussoukro: no advisory. Against all travel within 40 km of Burkina/Mali borders, northern Zanzan & Savanes, Comoé NP; all-but-essential within 20 km of Liberia border. Updated 29 May 2026', 'None found. Promotion via Côte d''Ivoire Tourisme (Ministry of Tourism) and the state-built Parc des Expositions d''Abidjan', 'Parc des Expositions d''Abidjan (PEA), Port-Bouët (opened 17 Jul 2023, EUR 115m): Convention Center 9,000 sqm, 5,000 seated to 10,000 standing; exhibition hall 7,200 sqm (divisible); 16 ha site; ~12,000 total. Secondary: Sofitel Abidjan Hôtel Ivoire (Palais des Congrès, ~2,000 — unverified)', 'ECOWAS visa-free; additional visa-free for Morocco, Tunisia, Mauritania, Chad, CAR, Congo, Gabon, Seychelles, Rwanda, South Africa, Uganda + Singapore, Philippines, Brazil, China etc.; e-visa (pre-enrolment online, collect at Abidjan airport, 48h, EUR 73, valid 90 days) for others; no all-Africans policy. Ease score: 3', '2026-11-04' from public.countries where name = 'Cote d''Ivoire' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'Informal', 'No', 5, 3, 1200, null, false, 'green', 'Cotonou: no advisory. Against all travel to Parc du W, Pendjari, within 5 km of Burkina border; all-but-essential to rest of Alibori & Atacora and the eastern strip to the Nigeria border. Updated 15 Dec 2025', 'None found (tourism promotion via Agence Nationale de Promotion des Patrimoines et du Tourisme — not verified this run)', 'Palais des Congrès de Cotonou (Marina blvd, 2003): main hall 1,200 seats (800+400 balcony); 300-seat conference room; 300-seat multipurpose hall; 10,053 sqm total. Sofitel Cotonou Marina (opened 2025) adds hotel conference space (capacity unverified)', 'Visa-free up to 90 days for ALL African nationals (since 2017); e-visa online + tourist VOA for others (since 2018); 72h free cruise visa; ranked 1st on Africa Visa Openness Index 2018–2021. Ease score: 5', '2026-11-04' from public.countries where name = 'Benin' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'Informal', 'No', 4, 3, null, null, false, 'green', 'Lomé: no advisory. Against all travel within 30 km of Burkina border (except Dapaong/N1); all-but-essential to rest of Savanes. Updated 15 Dec 2025', 'None found', 'Hôtel 2 Février (Radisson Blu), Lomé: 2,800 sqm event space, 9 rooms, largest room 1,600 sqm, total 1,854 pax, 320 guest rooms; theatre capacity of largest room unverified. Palais des Congrès de Lomé: capacity unverified (search budget exhausted)', 'Visa-free 30 days for ALL African passport holders from 18 May 2026 (online travel declaration 24h before arrival required); ECOWAS visa-free; e-visa via voyage.gouv.tg for others (XOF 25,000 single 1–15 days up to 65,000 for 31–90 days; max 5 working days; apply 6+ days ahead); courtesy visa free for official delegates. Ease score: 4', '2026-11-04' from public.countries where name = 'Togo' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'Informal', 'No', 3, 8, 300, null, false, 'green', 'No areas advised against. Risks: petty crime in Praia/Sal/Boa Vista, sea currents, seismic (Fogo/Brava). Updated 28 Jul 2026', 'None found (no bureau; "Cabo MICE" is a private DMC in Santa Maria)', 'No purpose-built convention centre verified. Hilton Cabo Verde Sal Resort: 300-seat auditorium + 3 x 60 rooms (hosted African Economic Conference 2021). Praia: Hotel Praia Mar / Pestana Trópico meeting rooms (capacities unverified). A EUR 39m tourism complex planned for Praia (search hit)', 'Visa-free for 19 African countries (ECOWAS 90 days; Angola/Guinea-Bissau/Mozambique 180; South Africa & Morocco 30) — list published Jul 2026; visa-free EU/UK/US etc. with mandatory EASE online pre-registration and airport security tax (TSA) paid 5+ days ahead; VOA suspended for 96 nationalities (pre-arrival visa via EASE). UN events have used courtesy visas on arrival. Ease score: 3', '2026-11-04' from public.countries where name = 'Cabo Verde' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'Informal', 'No', 4, 7, 1013, null, false, 'green', 'No areas advised against. Risks: checkpoints around Banjul, petty theft, "bumsters", power cuts, flooding Jun–Oct, cash economy. Updated 7 Jul 2026', 'Banjul International Convention Centre Ltd (BICC) — ex-OIC Secretariat converted to a state LLC Sept 2025 to manage SDKJ-ICC and Banjul airport VVIP lounge; venue-management company, not a destination bureau. Gambia Tourism Board handles promotion', 'Sir Dawda Kairaba Jawara ICC, Bijilo (opened Jan 2020, USD 50m Chinese-funded, 14,000 sqm): plenary hall 1,013; 4 x 200 thematic rooms; banquet halls 500 + 250; 11 bilateral rooms; claims 4,000+ total. Exhibition sqm: not stated', 'Visa-free for 15 African countries (11 ECOWAS + Mali, Niger, Burkina, Mauritania); widely reported as visa-free for all Africans (cited alongside Rwanda/Seychelles) but official list shows only 15; most EU/UK visa-free; others via Gambia Immigration Dept (gid.gov.gm/visa). Ease score: 4', '2026-11-04' from public.countries where name = 'Gambia' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'Informal', 'No', 3, 2, 700, null, false, 'red', 'Advises against ALL travel to whole country incl. Ouagadougou (updated 26 Oct 2026)', 'none found. Ouaga 2000 CIC is state-run; Chamber of Commerce (CCI-BF) organises flagship forums', 'Centre International de Conférences de Ouaga 2000, Ouagadougou — capacity unverified (no published figure found). Largest hotel plenary: LAICO Ouaga 2000, 700 theatre, 986 sqm total', 'ECOWAS nationals visa-free (still honoured after Jan 2025 ECOWAS exit); e-visa portal applicant.visaburkina.bf (launched 17 Aug 2023); visa FEES waived for all African nationals (Council of Ministers, 11 Sep 2025) but visa still required; non-Africans 94,000 XOF single / 122,000 XOF multi; VOA generally withdrawn; US nationals refused entry. No conference-visa scheme found. Ease: 3', '2026-11-04' from public.countries where name = 'Burkina Faso' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'No', 'No', 2, 0, 500, null, false, 'red', 'Advises against ALL travel to whole country incl. Bamako (JNIM blockades on routes into capital; kidnap threat). Updated 10 Jul 2026', 'none found. Office Malien du Tourisme et de l''Hôtellerie (OMATHO) listed as CVB-type contact on Cvent; no bid function', 'Centre International de Conférences de Bamako (CICB), Bamako; 11,800 sqm built area, Chinese-funded renovation reopened 26 Jan 2019; plenary seat count unverified. Largest hotel: Radisson Collection Bamako, Baobab room 500 theatre, 1,100 sqm, 11 rooms', 'Visa-free: 14 ECOWAS states + Cameroon, Morocco, Algeria, Chad, Mauritania, Tunisia (20 African) + Andorra, Monaco. Others: embassy visa; organiser-facilitated VOA via name list sent to authorities (UN practice). No e-visa confirmed. US nationals subject to retaliatory ban. Ease: 2', '2026-11-04' from public.countries where name = 'Mali' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'Yes', 'Yes', 'No', 3, 1, 2100, null, false, 'red', 'Advises against ALL travel incl. Niamey (attacks near Presidential Palace and airport). Updated 23 Oct 2026', 'Agence Nationale de l''Économie des Conférences (ANEC) — state agency; DG Mohamed Saidil Moctar; ICCA member (joined c.2020–21); email accreditation@anec-niger.ne; website not verified', 'Mahatma Gandhi International Convention Centre (MGICC), Niamey — 2,100-seat plenary, 800-seat banquet, 350-seat hall; opened Jan 2020 (India-built); exhibition sqm not published. Also Palais des Congrès 1,000 seats; 5,000-seat hall approved', 'Visa-free: ECOWAS + Morocco, Mauritania, Chad, Tunisia + AU/AfDB/UN laissez-passer. Others: embassy visa 25,000 XOF; where no Niger mission, ANEC-issued "flying visa" authorisation then VOA. No e-visa found. US nationals refused entry/transit (2025–26). Ease: 3 (Africans)', '2026-11-04' from public.countries where name = 'Niger' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'Informal', 'No', 3, 3, null, null, false, 'green', 'No advice against travel found; Conakry flagged for carjacking in outlying suburbs; pre-arrange airport transfers after dark. Updated 12 Aug 2026', 'none found', 'Palais du Peuple, Conakry (1967 China-built, renovated 2008) — seat capacity unverified. Largest hotel: Sheraton Grand Conakry 574 sqm meeting space, 240 rooms (largest room theatre figure not published)', 'Visa-free: ECOWAS + Algeria, Egypt, Morocco, Tanzania (+ some diplomatic incl. Zimbabwe). Others: e-visa (online, ~72h) then biometric VOA counter at Conakry; tourist $80, transit $50, 1-yr $150. No all-Africans policy or conference scheme found. Ease: 3', '2026-11-04' from public.countries where name = 'Guinea' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'No', 'No', 3, 1, null, null, false, 'green', 'No advice against travel found; petty crime in Bissau; landmine caution outside capital. Updated 10 Dec 2025 (pre-coup page date)', 'none found', 'none verified. Ledger Plaza Bissau (164 rooms) is main business hotel; meeting capacity not published. Hotel Ceiba secondary', 'ECOWAS visa-free (1980); CPLP diplomatic passports free. Others: VOA at Osvaldo Vieira airport and 4 land posts — €85 (Jan 2024), exact cash only (EUR/USD/XOF), 45 days. E-visa (rgb-visa.com) SUSPENDED. No all-Africans or conference scheme found. Ease: 3', '2026-11-04' from public.countries where name = 'Guinea-Bissau' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'Informal', 'No', 4, 0, 1500, null, false, 'green', 'No advice against travel found; pickpocketing/mugging risk in Freetown (Lumley Beach, Aberdeen, Congo Cross). Updated 19 Jun 2026', 'none. National Tourist Board (under Ministry of Tourism & Cultural Affairs) handles promotion; Ministry directly hosts congresses; "MICE ambitions" stated 2026 but no bureau announced', 'President Julius Maada Bio International Conference Centre, Lungi — 1,500-seat plenary, 500-seat banquet, exhibition spaces (sqm not published); built by FB Group (Turkey), commissioned Jul 2026; 5-star hotel planned adjacent. Secondary: Bintumani ICC "New Hall", Aberdeen, Freetown (capacity unverified)', 'ECOWAS visa-free; VOA for ~80 countries at Lungi (US$80); AU citizens US$25 (free for Botswana, Eswatini, Kenya, Lesotho, Malawi, Mauritius); e-visa at evisa.sl; organising committees routinely secure VOA/invitation letters; courtesy VOA for diplomatic/UN passports with ministry letter. Ease: 4', '2026-11-04' from public.countries where name = 'Sierra Leone' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
