();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'Informal', 'No', 2, 2, 800, null, false, 'amber', 'Advises against ALL BUT ESSENTIAL travel to N''Djamena; against ALL travel to Lake Chad, northern provinces, Kanem and 30 km of all borders. Updated 6 Aug 2026', 'none found (ANIE investment agency co-hosts investor events; Office National de Promotion du Tourisme not verified)', 'Radisson Blu N''Djamena auditorium — 800 seats / 600 sqm, 13 meeting rooms, 175 rooms (largest verified). Palais du 15 Janvier (parliament/conference, capacity unverified). N''CCI 1,200-seat centre announced 2013 — completion unverified. Toumaï Palace hotel (242 rooms, 6 meeting rooms, Hilton-managed planned, handed over Jul 2025)', 'CEMAC nationals visa-free; many African diplomatic passports free. e-Visa at evisa.td launched 11 Dec 2024; all applications online-only from 11 May 2026; prior VOA via organiser-requested immigration authorisation (50,000 XAF). Announced: visa-free for ALL African nationals from 1 Jan 2027. Police registration within 72h. US citizens: visa issuance suspended since 5 Jun 2025. Ease: 2 now / 4 for Africans from 2027', '2026-11-04' from public.countries where name = 'Chad' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
