insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'Informal', 'No', 1, 4, 3000, null, false, 'green', 'Kinshasa city not restricted except: all-but-essential travel to N''djili and Kimbanseke districts (south of airport access road) and the N1 east of Menkao. All travel advised against in eastern provinces (N/S Kivu, Ituri, Haut-Uélé, Maniema, Tanganyika, Haut-Lomami, Kwamouth). Updated 8 Oct 2026, current at 3 Nov 2026', 'none. Kinshasa Congress & Finance Centre (Centre Financier de Kinshasa) is a government-owned complex (opened 19 Dec 2023; hotel run by Milvest/Marriott on 49-yr contract)', 'Kinshasa Congress & Finance Centre, Kinshasa (Gombe). Amphitheatre 3,000 seats (Forbes Afrique) / auditoriums total 2,698 (architect); Congress Centre 43,000 m²; 240-room Marriott on site. Exhibition sqm: not stated. Alternative: Pullman Grand Hotel Kinshasa "Chapiteau" 600 theatre', 'Visa required (UK incl.). e-visa announced Nov 2024 for early 2025: USD 300 + USD 90 at entry, 7-day stay, all entry points (launch date unconfirmed); visa-on-arrival only for Mauritius (7 days), DRC-origin holders, and "visa volant" email pre-approval where no DRC embassy; no all-Africans policy; Uganda/Chad exemption agreements not in force. Ease score: 1', '2026-11-04' from public.countries where name = 'DR Congo' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'Informal', 'No', 2, 1, null, null, false, 'green', 'No regional travel restrictions listed. Malabo/Bata: petty theft to armed robbery; robberies of taxi passengers at night; use pre-booked taxis. Updated 8 Jan 2026', 'none. Sipopo Congress Centre is state-owned (built 2011 for AU Summit)', 'Sipopo Congress Centre, Sipopo (Malabo). Built area 13,708 m²; completed Jun 2011; plenary seat count: unverified (architect pages give no figure; hosted 17th AU Summit 2011 and AfDB 2019 AM). Exhibition sqm: not stated', 'e-visa for all nationalities since 1 Jul 2023 (USD 75; must arrive via Malabo airport); visa issued at border against printed e-visa letter (FCDO); visa-free: CEMAC nationals only; VOA: UAE only; no all-Africans policy. Ease score: 2', '2026-11-04' from public.countries where name = 'Equatorial Guinea' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'Informal', 'No', 1, 0, 350, null, false, 'red', 'Advises against ALL travel to whole country except Bangui; ALL BUT ESSENTIAL travel to Bangui incl. M''Poko airport. Updated 28 May 2026', 'none', 'Hotel Ledger Plaza Bangui: NBAKO room 340 m², 350 theatre; KOTANGOU hall ~2,842 m² (no theatre figure published); 156 guest rooms. (Government Palais de la Renaissance / Assemblée: capacity unverified)', 'Visa required; British nationals apply at CAR Embassy Paris (no UK mission); event-specific visa-on-arrival with pre-approval + invitation letter was arranged for African Caucus 2025 (costs borne by delegates); CEMAC nationals visa-free; no e-visa found; no all-Africans policy. Ease score: 1', '2026-11-04' from public.countries where name = 'Central African Republic' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'No', 'No', 4, 1, 100, null, false, 'green', 'No areas under restriction. Updated 10 Dec 2025', 'none (Direcção Geral do Turismo e Hotelaria handles tourism; no MICE unit found)', 'Pestana Miramar São Tomé: 1 room, 146 m², 100 theatre, 59 rooms. Larger: Centro de Conferências / Pestana São Tomé (hosted CPLP summit 2023) — capacity unverified', 'Visa-free up to 15 days for UK and many nationalities (tourism); e-visa (e-VisaST, smf.st/evisa, 7 working days) for others; holders of Schengen/US visa or residence permit: 15 days visa-free; reciprocal visa-free with Togo and several African states (Angola, Cabo Verde, Eq. Guinea, Gabon, Morocco, Mozambique, Rwanda listed in change log); no explicit all-Africans policy. Ease score: 4', '2026-11-04' from public.countries where name = 'Sao Tome and Principe' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'Yes', 'Yes', 'No', 3, 10, 3000, null, false, 'green', 'Luanda not restricted. All-but-essential travel to Cabinda Province (except Cabinda city) and within 1 km of DRC border in Lunda Norte. Luanda: care at ATMs/banks (follow-and-rob risk); carry ID (15,000 Kz fine)', 'Angola Convention Bureau (ACB), programme "Meet in Angola – The Meeting Room of Africa"; parent: Ministry of Tourism, housed at Infotur (Instituto de Fomento Turístico); launched 6 May 2026, Luanda; Director Margarida Gorjão-Henriques; international debut IMEX Frankfurt May 2026 (11 co-exhibitors). Website: none found (meetinangola domain appears in search results, unverified)', 'Palácio de Convenções de Luanda (Chicala, Ingombota), opened 24 Aug 2026: 3,000-seat multipurpose theatre on an 80,000 m² site; exhibition sqm not stated. Also: Centro de Convenções de Talatona (CCTA): main auditorium 700, large indoor exhibition halls (sqm unverified), 12 km from airport', 'Visa-free 30 days (tourism only) for 98 nationalities since Oct 2023 incl. UK, EU, US, China, India, 14 African states (e.g. Botswana, Cabo Verde, Eq. Guinea, Morocco, Rwanda); business/conference visas still required in advance via consulate (FCDO); e-visa: not mentioned by FCDO; no all-Africans policy. Ease score: 3', '2026-11-04' from public.countries where name = 'Angola' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'Yes', 'Yes', 'No', 3, 65, 3000, 6, false, 'green', 'Addis Ababa: no advisory. "Advise against all travel" to Tigray, Amhara, Gambela and all border zones; "all but essential" to parts of Afar, East/North Shewa (Oromia), Somali, Benishangul-Gumuz', 'Ethiopia Convention Bureau (ECB), brand "MICE Ethiopia / Meet in the Land of Origins"; parent: Tourism Ethiopia (federal); formed 2020, national launch Jan 2021; 8 staff; 3-yr strategic plan budget USD 3.4m (World Bank-funded consultants). Separate city-level Addis Ababa Convention Bureau (reports to Mayor''s office, opened July 2019). Website: none found (Cvent listing exists)', 'Addis International Convention Centre (AICC), Addis Ababa, opened 1 Mar 2025, 40 ha site; two large halls "3,000–4,000 people" each; 8 smaller rooms; outdoor exhibition for 50,000; indoor exhibition sqm not published. Phase 2 approved (7.54bn birr, 36 months): 3,100-seat plenary + 2 auditoria + expanded trade-fair halls. Centre posted 150.4m birr loss and 46% vacancy in 2024/25. (Also UNECA Conference Centre and AU Nelson Mandela Hall — capacities unverified)', 'Visa required for most; e-visa (evisa.gov.et) tourist 30-day single-entry US$62 (cut from $82, Aug 2024); 90-day e-visa discontinued; dedicated e-Conference Visa page on evisa.gov.et (since Oct 2017); visa-on-arrival announced for all African nationals (Oct/Nov 2018) but Ethiopian Airlines guideline says VOA is tourist-only, for "eligible countries", with meetings requiring advance Immigration approval; overstay fine US$30/day. Ease score: 3/5', '2026-11-04' from public.countries where name = 'Ethiopia' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'Yes', 'Informal', 'No', 4, 5, 1783, 15, true, 'green', '"Advise against all but essential travel" only within 20 km of Mozambique/Cabo Delgado border; Dar, Arusha, Zanzibar: no advisory', 'Tanzania National Convention Bureau (NCB) — housed "for the time being" within Tanzania Tourist Board (TTB), Ministry of Natural Resources & Tourism; announced Aug 2018; no standalone website found; by Aug 2025 TTB still presents MICE itself (no separate brand visible)', 'Julius Nyerere International Convention Centre (JNICC), Dar es Salaam: largest hall 1,783 theatre; largest meeting room 1,003; 3,609 sqm exhibition; 12 rooms; gov-owned, AICC-operated (built 2010–12). Arusha AICC aged; new 5,000-seat Arusha convention centre under construction (2025)', 'Visa-free: EAC, SADC (except Comoros), Commonwealth (except UK, Canada, Nigeria, India, Pakistan, Australia, NZ); e-visa (visa.immigration.go.tz) and VOA at main ports for most others; ordinary single-entry US$50 (90 days), multiple US$100, business US$250; US citizens must take multiple ($100); ~20 nationalities (incl. Nigeria, Somalia) need special permission. Ease score: 4/5', '2026-11-04' from public.countries where name = 'Tanzania' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'Yes', 'Yes', 'No', 3, 1, 3800, 19, true, 'green', 'Kampala: no advisory level; terrorism noted "including Kampala"; "exercise particular caution" in west near DRC border; Ebola precautions update (Oct/Nov 2026)', 'Uganda Convention Bureau (UCB) under Uganda Tourism Board (UTB, utb.go.ug); established via World Bank CEDP project from 2018; described as "fully functional" by 2024; Senior MICE Officer Mellon Tukeikiriza', 'Speke Resort Munyonyo Convention Centre, Kampala — main hall + gallery "over 3,800" seats, opened early 2024 (government co-invested); exhibition sqm not published', 'Visa required for most (EAC, some COMESA/African states exempt — list not retrieved); online-only (visas.immigration.go.ug) with approval letter shown on arrival, "no visas issued on arrival"; single-entry US$50, multiple US$100–200; East Africa Tourist Visa US$100 (Kenya/Rwanda/Uganda, 90 days); conference letter required even for exempt nationals. Ease score: 3/5', '2026-11-04' from public.countries where name = 'Uganda' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'No', 'No', 3, 0, null, null, false, 'green', '"Advise against all travel to parts of Burundi" — named communes of Bujumbura Province (Mugina, Cibitoke, Bubanza, Mpanda, parts of Ntahangwa near RN5/Rusizi), RN6/RN10 through Kibira; Bujumbura city not under blanket advisory; Gitega not mentioned', 'None; tourism body: Burundi National Tourism Office (ONT) — listed as CVB on Cvent, no MICE services, no website found', 'No convention centre. Hotels: Hotel Club du Lac Tanganyika (UNECA ICSOE venue), Royal Palace Hotel (EACO Congress venue); Burundi Palace Hotel (1 room, 70 sqm). Max theatre capacity unverified (likely <600)', 'Visa required; VOA at Bujumbura airport and all land borders (1 month) and e-visa via migration.gov.bi (1 mo US$90, 2 mo $180, 3 mo $270; payable online or cash on arrival); EAC citizens exempt; mandatory online entry/exit registration. Ease score: 3/5', '2026-11-04' from public.countries where name = 'Burundi' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'No', 'No', 2, 0, 550, null, false, 'red', '"Advises against all travel to South Sudan" (armed violence, criminality); Juba airport may close during unrest', 'None', 'Hotel venues: Radisson Blu Juba — ballroom 550 auditorium, 890 sqm, 5 rooms; Imperial Plaza Hotel (ICPAC GHACOF venue); Freedom Hall (government, capacity unverified)', 'Visa required; e-visa for all nationalities (evisa.gov.ss) single/multiple; visa-free: Kenya, Tanzania (+2 unnamed); VOA only for diplomatic/official/UN; fee not published on FCDO. Ease score: 2/5', '2026-11-04' from public.countries where name = 'South Sudan' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'No', 'No', 2, 0, null, null, false, 'red', '"Advises against all travel to Somalia, including Somaliland", except Awdal, Maroodijeh (Hargeisa), Sahil regions = "all but essential travel"; FCDO support "severely limited"', 'None (SomInvest promotes investment conferences)', 'Afisiyoone Conference Center, Mogadishu (NIRA conference venue, capacity unverified); Jazeera Palace Hotel (1 room); Halane/airport-zone venues', 'Mandatory e-visa for all foreigners from 1 Sep 2025 (fees to government accounts; portal had a reported data breach — FCDO says "consider the risks"); Mogadishu arrivals need e-visa; Somaliland rejects it, issues its own 1-month VOA at Hargeisa; invitation letter may be required. Ease score: 2/5', '2026-11-04' from public.countries where name = 'Somalia' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'Informal', 'No', 3, 4, 1200, null, false, 'green', '"Advises against all travel" only to the Djibouti–Eritrea border; Djibouti City: no advisory', 'None; tourism body: Office National du Tourisme de Djibouti / Agence Nationale du Tourisme (ANT, est. 1969), DG Osman Abdi Mohamed, under Ministry of Commerce & Tourism', 'Djibouti Palace Kempinski — Nakheel Ballroom 1,200 theatre (960 sqm), >1,150 sqm total, 4 breakout rooms; Fairmont (~1,398 sqm events) and Radisson planned/opened 2024; Palais du Peuple (govt, capacity unverified)', 'Visa required; e-visa (evisa.gouv.dj) since Feb 2018: transit US$12 (1–14 d), short-stay US$23 (15–90 d); tourist VOA still obtainable at airport paying USD cash (FCDO) but officially only for diplomatic/service; proof of onward travel required. Ease score: 3/5', '2026-11-04' from public.countries where name = 'Djibouti' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'No', 'No', 1, 0, 420, null, false, 'red', '"Advises against all travel" within 25 km of all land borders; "all but essential travel" to the rest of Eritrea (incl. Asmara); embassy staff need permits to leave Asmara', 'None (Ministry of Tourism only)', 'Hotel Asmara Palace (ex-InterContinental) — Salon Keren 420 theatre (508 sqm), 1,109 sqm total meeting space, 170 rooms', 'Visa required for all except Ethiopian and Ugandan passport holders; no e-visa; embassy application, or government-arranged VOA for approved conferences (passport details 3 weeks ahead, visa permission letter); travel permits needed outside Asmara; dual nationals treated as Eritrean. Ease score: 1/5', '2026-11-04' from public.countries where name = 'Eritrea' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'Informal', 'No', 2, 15, 1670, 28, true, 'green', 'Cairo, Sharm El Sheikh, Alexandria, Luxor, Hurghada: no advisory. Against all travel: North Sinai, 20 km Libya border. All-but-essential: parts of South Sinai interior, Ismailiyah east of Suez Canal, most Western Desert, Hala''ib. Updated 27 Oct 2026', 'No dedicated national convention bureau found. Nearest body: Egypt Expo & Convention Authority (EECA), affiliated to Ministry of Investment & Foreign Trade; operates Cairo Int''l Convention & Exhibition Centre, Nasr City. Year/website: unverified', 'Al Manara Int''l Conference Center, New Cairo — main theatre 1,670 seats. Largest exhibition: Egypt Int''l Exhibition Center (EIEC), New Cairo — 10,080 sqm max single-floor exhibit space (total unverified). Cairo ICEC Nasr City ~22,480 sqm total meeting space (Cvent), theatre capacity not published. COP27 used Sharm El Sheikh Int''l Convention Centre (capacity unverified)', 'Visa required for most; VOA (USD 30 cash; digital VOA at Cairo from 1 Aug 2026 USD 36 card) for UK/US/EU/AUS/CAN/JPN/KOR etc.; e-visa stated to cover 180+ nationalities but most African ordinary passports must apply at embassy; no all-Africans policy; Sudan (from 24 Sep 2024), Ethiopia, Mali, Niger need security clearance (up to 3 months); 15-day free Sinai stamp (Sharm/Dahab/Nuweiba/Taba) for UK/US/EU only. Ease score: 2 (for African delegates); 4 for Western delegates', '2026-11-04' from public.countries where name = 'Egypt' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'Partial (MCB status unverified; ONMT runs MICE)', 'Yes', 'No', 3, 8, 2000, 43, true, 'green', 'No advise-against areas; Marrakech, Casablanca, Rabat unrestricted; closed Algeria border; Western Sahara separate advice. Updated 19 Aug 2026', 'Morocco Convention Bureau (MCB) — created via MoU between ONMT (Office National Marocain du Tourisme) and Confédération Nationale du Tourisme, announced Sep 2017; current operating status and website: unverified (ONMT runs MICE roadshows directly; MICE promotion in practice sits in ONMT)', 'Palais des Congrès de Marrakech (Mövenpick Mansour Eddahbi) — largest room 1,489, 2,600 sqm exhibition; Int''l Convention Center Mohammed VI, Skhirat (Rabat) — 2,000 (marquee), ~10,200 sqm exhibit. National capacity stated as ~135,000 seats. Pipeline: Agadir 5,000-seat centre (end-2026); Marrakech Convention & Exhibition Center, 4,000-seat auditorium, 10,000 participants, up to 250,000 sqm, opening ~2028; Casablanca centre under study for 2030; Rabat exhibition centre MAD 700m', 'Visa-free 90 days for UK/EU/US and many; visa-free African states: Algeria, Burkina Faso, Cape Verde, Gabon, Ghana (from Jun 2025), Guinea, Mali, Niger, Rep. Congo, Senegal, Togo, Tunisia (Côte d''Ivoire removed Sep 2024); e-visa since 10 Jul 2022 for listed nationalities and for holders of valid Schengen/US/UK etc. visas; AEVM electronic travel authorisation being rolled out for visa-exempt nationals; special e-visa for AFCON 2025 fans (8 African nations). No all-Africans policy. Ease score: 3', '2026-11-04' from public.countries where name = 'Morocco' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'Yes (private-sector TCB, 2021)', 'Informal', 'No', 3, 0, 2500, 13, true, 'green', 'Tunis, Hammamet, Sousse, Monastir, Djerba: no advisory. Against all travel: Chaambi/Mt Salloum/Sammamma/Mghila zones, militarised zone south of El Borma–Dhehiba, 20 km Libya border, Ben Guerdane. All-but-essential: Kasserine Gov., parts of Algeria border, within 75 km of Libya border (Zarzis excluded). Updated 24 Jul 2026', 'Tunisie Convention Bureau (TCB) — private-sector professional body founded 2021, president Mohamed Jerad; partners with Ministry of Tourism & Handicrafts and ONTT (national tourist office, DG Mehdi Haloui); website: unverified', 'Medina Convention & Expo Centre, Hammamet — up to 2,500 delegates; Int''l Congress Centre of Utica (Tunis) 1,500; Palais des Congrès de Tunis 1,200; El Mouradi, Port El Kantaoui 1,200; Kram Exhibition Center (Parc des Expositions du Kram), Tunis — 3 halls of 4,000–10,000 sqm + 5,000 sqm multi-purpose', 'Visa-free 90 days for UK/EU/US and most Western; from Jul 2026 visa-free 90 days for 22 African states (Algeria, Angola, Benin, Burkina Faso, Cabo Verde, Comoros, Côte d''Ivoire, Eq. Guinea, Gabon, Gambia, Guinea, Guinea-Bissau, Libya, Mali, Mauritania, Mauritius, Morocco, Namibia, Niger, Senegal, Seychelles, South Africa); no e-visa (platform tender declared unsuccessful Aug 2025); no VOA; Zimbabwe/Kenya/Nigeria etc. need embassy visa. Ease score: 3', '2026-11-04' from public.countries where name = 'Tunisia' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'Informal', 'No', 1, 1, 6000, 2, false, 'green', 'Algiers, Oran: not named in restricted zones (regional-risks page not retrievable). Against all travel: 30 km of Libya, Mauritania, Mali, Niger borders; 30 km Tunisia border in Illizi/Ouargla; Chaambi area. All-but-essential: 30 km of rest of Tunisia border. Updated 25 Sep 2026', 'none (no convention bureau found; events run through Ministry of Tourism / state agencies; CIC Algiers is state-owned)', 'Centre International de Conférences Abdelatif Rahal (CIC), Club des Pins, Algiers — auditorium 6,000 seats; two exhibition halls of 12,400 sqm each; ~11,000 sqm meeting space (Cvent); opened 8 Sep 2016; built by CSCEC', 'Visa required in advance for nearly all incl. UK/EU/US and almost all Africans (short exempt list, mainly Maghreb/Sahel; Morocco visa required since Sep 2024); VOA only for organised tours to southern Saharan wilayas via approved agency (Dec 2024 proposal to extend nationwide — status unverified); e-visa only "under consideration" for Saharan tourists (Nov 2024); IATF 2025 showed event-specific facilitation (group consular applications, exceptional VOA with MFA boarding clearance, border regularisation visa for countries without Algerian mission; fees still apply). Ease score: 1', '2026-11-04' from public.countries where name = 'Algeria' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'No', 'No', 1, 0, null, null, false, 'amber', 'Against all travel to most of Libya; against all but essential travel to Tripoli, Benghazi, Misrata, Al-Bayda, Derna, Jebel Akhdar. Updated 21 Jul 2026', 'none; state body: General Authority for Exhibitions and Conferences (Tripoli) organises Tripoli International Fair; year/website unverified', 'Tripoli International Fairground (historic exhibition grounds; 10,000 sqm hall listed for Tripoli Int''l Conference Centre); plenary theatre capacity: unverified', 'Visa required; e-visa launched 21 Mar 2024 (USD 63, single entry, 30 days) but only via tour operator/local sponsor with security letter; visa-free: Tunisia; Algeria (Mitiga/Misrata only); Mauritania (restored Aug 2026); Malaysia (Jun 2026); partial Egypt/Turkey by age/gender; VOA suspended; police registration within 7 days; overseas visas may not be recognised at all ports (east/west split). Ease score: 1', '2026-11-04' from public.countries where name = 'Libya' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'No', 'No', 1, 0, null, null, false, 'red', 'Against all travel to all of Sudan (Khartoum included); British Embassy Khartoum closed, no consular staff in country. Updated 11 May 2026', 'none', 'Friendship Hall, Khartoum — status/condition post-war unverified; capacity unverified', 'Visa required in advance via Sudanese embassy; exit visa may be required on single-entry; registration with Aliens Dept within 3 days (fee, 2 photos); VOA only for a short list (must arrive direct from country of citizenship) and Sudanese-descent/spouses; no e-visa; Israel passport ban. Ease score: 1', '2026-11-04' from public.countries where name = 'Sudan' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'Informal', 'No', 3, 0, 3200, null, false, 'green', 'Nouakchott: no advisory; Nouadhibou explicitly excluded from border advisory. Against all travel: eastern Mauritania (east of Kankossa–Zouerat–Fderîck line), 25 km Mali border. All-but-essential: 25 km Western Sahara border (road/Nouadhibou excluded), Tiris Zemmour, Assaba, Hodh el Gharbi, Gorgol, Guidimaka, parts of Adrar/Tagant. Updated 19 Oct 2026', 'none found', 'Al Mourabitoune Conference Center (Palais des Congrès), Nouakchott, 2 km from airport — main hall 3,200 seats (2,200 + 1,000 balcony), ~24,000 sqm built area; exhibition sqm unverified; hosts Mauritanides', 'Universal e-visa since 5 Jan 2025 (apply online via ANRPTS before boarding; VOA abolished; embassies no longer issue visas; fee paid cash EUR/USD on arrival, exact amount); visa-free ~10 countries incl. regional neighbours (AU 2017 note listed Libya, Tunisia, Algeria, Senegal, Mali, Gambia, Côte d''Ivoire, Niger, Guinea-Bissau as passport-only); historic fee USD 45 for African/Arab nationals vs USD 60 others; no all-Africans policy. Ease score: 3', '2026-11-04' from public.countries where name = 'Mauritania' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'Yes', 'Yes', 'Yes (SANCB Bid Support Programme)', 3, 18, 6000, 98, true, 'green', 'No areas advised against. Warnings: violent crime; airport-follow robberies (JNB), hire-car targeting on CPT airport routes (avoid R300/Borcherds Quarry), express kidnappings, protests that turn violent, xenophobic marches, e-hailing strike violence, lone-actor terror possible. Durban: general warnings only', 'South Africa National Convention Bureau (SANCB); parent: South African Tourism; est. 2012; southafrica.net/business', 'Durban ICC (Inkosi Albert Luthuli ICC + Arena), Durban: Arena 10,000 theatre; 21,820 m² exhibit floor; AIPC lists 6,000 theatre seats / 112,188 m² total complex. CTICC, Cape Town: Auditorium 1 = 1,500 theatre; 11,200 m² column-free exhibition (CTICC 1+2)', 'Visa-free 90 days: UK, EU, US, Canada, Australia, Japan etc.; 22 African states visa-free incl. all SADC + Kenya, Rwanda, Tunisia, Algeria, Benin, Côte d''Ivoire, Gabon, Guinea, Cabo Verde; AU/SADC/UN laissez-passer accepted. Nigeria, Ghana, India, China, Egypt need visa. ETA: piloted Oct 2025 (China, India, Indonesia, Mexico; G20 delegates), official launch 12 Aug 2026 at JNB; expansion to all visa-required nationals targeted Sept 2026; proposed R500 fee (R925 total with visa fee); ETA only at JNB/CPT/Lanseria. No all-Africans policy. Conference-specific facilitation: SANCB liaises with Home Affairs for delegate visas (unverified). Online traveller declaration mandatory from 1 Jul 2026. Ease score: 3', '2026-11-04' from public.countries where name = 'South Africa' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'Informal', 'Partial (MICE VAT exemption, 50+ pax)', 4, 17, 3500, null, false, 'green', 'No areas advised against. Oct 2026: unrest after a police shooting (9 Oct) with island-wide evening curfews 12–18 Oct, now lifted; petty crime hotspots Port Louis, Grand Baie, Flic en Flac; cyclone season Nov–May', 'None dedicated. MICE promotion by Mauritius Tourism Promotion Authority (MTPA, mymauritius.travel) under Ministry of Tourism; Economic Development Board (EDB, est. 2017) runs incentive schemes', 'Swami Vivekananda International Convention Centre (SVICC), Pailles/Port Louis: Main Hall 3,500 theatre (MTPA claims up to 5,000); ~3,500 m² meeting/exhibition space; Trianon Convention Centre 3,000; Freeport Exhibition Centre 1,000', 'Visa-free (up to 90 days/visit; UK 60 days per FCDO) for most European, N. American, Commonwealth and many African nationals; visa-on-arrival groups (60-day and 14-day); a small set must apply in advance; All-in-One Travel Form (online, free); no ETA fee. Ease score: 4', '2026-11-04' from public.countries where name = 'Mauritius' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'Informal', 'No', 3, 2, 2500, null, false, 'green', 'Maputo NOT in advisory zones. Advise against all travel: Cabo Delgado (exc. Palma/Pemba/Afungi), Memba & Eráti (Nampula), Mecula & Marrupa (Niassa); all-but-essential: Palma, Pemba, Afungi. Maputo: armed street crime, kidnap-for-ransom of business people, protests at short notice (toll gates vulnerable). Updated 20 Aug 2026', 'None. INATUR (Instituto Nacional do Turismo) under Ministry of Culture & Tourism promotes tourism; no business-events unit found', 'Centro Internacional de Conferências Joaquim Chissano (CICJC), Maputo, opened 2003; multi-use hall ~2,500 pax (2012–16 extension); exhibition sqm not found; website cicjc.gov.mz (blocked)', '2023 decree: 28–29 countries (UK, US, Canada, EU majors, China, Japan, Korea, UAE, Saudi, Ghana, Senegal, Côte d''Ivoire etc.) visa-exempt BUT must pre-register ≥48h and pay MZN 650 processing (now styled an ETA; FCDO: ~US$47 total for UK nationals, apply ≥5 working days ahead, cannot pay on arrival). SADC nationals visa-free. e-Visa portal (evisa.gov.mz) open to 52 African nationalities (6 barred in 2026, unnamed). Ease score: 3', '2026-11-04' from public.countries where name = 'Mozambique' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'Informal', 'No', 3, 0, 1500, null, false, 'green', 'No areas advised against (updated 20 Oct 2026). Risks: kidnap-for-ransom, muggings near bus stations, rising break-ins in Lilongwe/Blantyre/Limbe, political/economic demonstrations, chronic fuel shortages, Nov–Apr floods', 'None. Dept of Tourism (Ministry of Tourism); no bureau found', 'Bingu International Convention Centre (BICC), Lilongwe, opened 2015 (China Exim-funded, with Presidential Hotel): three halls 1,500 combined; 5,000-person event square; auditorium capacity not stated. New: Sunbird Livingstonia ICC (K11bn) announced', 'Two-tier (Aug 2026): 160 countries "visa-free or simplified" (= visa on arrival, US$50 single; $150 6-month multi; $250 1-yr); 47 countries need prior authorisation (incl. China, India, Morocco, Burundi). FCDO: UK nationals must obtain visa (on arrival, cash USD) or e-visa via Malawi Immigration. SADC nationals exempt (unverified). Ease score: 3', '2026-11-04' from public.countries where name = 'Malawi' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
insert into public.destination_profiles (country_id, profile_depth, bureau_exists, bids_formally, subvention_fund, visa_ease, intl_nonstops, largest_plenary, icca_2024_meetings, icca_2024_top10, advisory_level, fcdo_summary, bureau_detail, venue_detail, visa_detail, verified_on) select id, 'base', 'No', 'No', 'No', 3, 0, null, null, false, 'green', 'No areas advised against (updated 10 Dec 2025). Occasional political demonstrations, muggings, armed carjacking in urban areas, thefts peak pre-Christmas/Easter', 'None. Lesotho Tourism Development Corporation (LTDC) promotes; has invited proposals for a MICE anchor project', '''Manthabiseng National Convention Centre, Maseru; capacity not found (LTDC itself calls it "decent" but short on accommodation/services); Avani Maseru / Avani Lesotho hotels for smaller meetings', 'Visa-free 90 days for UK (and most Commonwealth/EU/US – unverified); SADC visa-free; e-visa exists (evisalesotho.com – unverified); all air/land access routes via South Africa so SA entry rules also apply. Ease score: 3', '2026-11-04' from public.countries where name = 'Lesotho' and type = 'country' on conflict (country_id) do update set profile_depth = excluded.profile_depth, bureau_exists = excluded.bureau_exists, bids_formally = excluded.bids_formally, subvention_fund = excluded.subvention_fund, visa_ease = excluded.visa_ease, intl_nonstops = excluded.intl_nonstops, largest_plenary = excluded.largest_plenary, icca_2024_meetings = excluded.icca_2024_meetings, icca_2024_top10 = excluded.icca_2024_top10, advisory_level = excluded.advisory_level, fcdo_summary = excluded.fcdo_summary, bureau_detail = excluded.bureau_detail, venue_detail = excluded.venue_detail, visa_detail = excluded.visa_detail, verified_on = excluded.verified_on, updated_at = now();
