insert into public.destination_profile_fields (country_id, field_no, field_group, field, value, source_url, confidence, verified_on) select id, 1, 'Institutional', 'Convention bureau / business-events body', 'Ethiopia Convention Bureau (ECB), brand "MICE Ethiopia / Meet in the Land of Origins"; parent: Tourism Ethiopia (federal); formed 2020, national launch Jan 2021; 8 staff; 3-yr strategic plan budget USD 3.4m (World Bank-funded consultants). Separate city-level Addis Ababa Convention Bureau (reports to Mayor''s office, opened July 2019). Website: none found (Cvent listing exists)', 'https://addisfortune.news/national-convention-bureau-gears-up-for-launch', 'verified', '2026-11-04' from public.countries where name = 'Ethiopia' and type = 'country' on conflict (country_id, field_no) do update set value = excluded.value, source_url = excluded.source_url, confidence = excluded.confidence, verified_on = excluded.verified_on, field_group = excluded.field_group, field = excluded.field;
