insert into public.destination_profile_fields (country_id, field_no, field_group, field, value, source_url, confidence, verified_on) select id, 4, 'Access', 'Visa regime and ease score', 'Visa required for most; e-visa (evisa.gov.et) tourist 30-day single-entry US$62 (cut from $82, Aug 2024); 90-day e-visa discontinued; dedicated e-Conference Visa page on evisa.gov.et (since Oct 2017); visa-on-arrival announced for all African nationals (Oct/Nov 2018) but Ethiopian Airlines guideline says VOA is tourist-only, for "eligible countries", with meetings requiring advance Immigration approval; overstay fine US$30/day. Ease score: 3/5', 'https://www.gov.uk/foreign-travel-advice/ethiopia/entry-requirements', 'verified', '2026-11-04' from public.countries where name = 'Ethiopia' and type = 'country' on conflict (country_id, field_no) do update set value = excluded.value, source_url = excluded.source_url, confidence = excluded.confidence, verified_on = excluded.verified_on, field_group = excluded.field_group, field = excluded.field;
