insert into public.destination_profile_fields (country_id, field_no, field_group, field, value, source_url, confidence, verified_on) select id, 6, 'Capacity', 'Largest plenary venue', 'Addis International Convention Centre (AICC), Addis Ababa, opened 1 Mar 2025, 40 ha site; two large halls "3,000–4,000 people" each; 8 smaller rooms; outdoor exhibition for 50,000; indoor exhibition sqm not published. Phase 2 approved (7.54bn birr, 36 months): 3,100-seat plenary + 2 auditoria + expanded trade-fair halls. Centre posted 150.4m birr loss and 46% vacancy in 2024/25. (Also UNECA Conference Centre and AU Nelson Mandela Hall — capacities unverified)', 'https://www.fanamc.com/english/pm-abiy-ahmed-inaugurates-addis-international-convention-center-ethiopias-largest/', 'partial', '2026-11-04' from public.countries where name = 'Ethiopia' and type = 'country' on conflict (country_id, field_no) do update set value = excluded.value, source_url = excluded.source_url, confidence = excluded.confidence, verified_on = excluded.verified_on, field_group = excluded.field_group, field = excluded.field;
