insert into public.destination_profile_fields (country_id, field_no, field_group, field, value, source_url, confidence, verified_on) select id, 4, 'Access', 'Visa regime and ease score', 'Visa-free 90 days: UK, EU, US, Canada, Australia, Japan etc.; 22 African states visa-free incl. all SADC + Kenya, Rwanda, Tunisia, Algeria, Benin, Côte d''Ivoire, Gabon, Guinea, Cabo Verde; AU/SADC/UN laissez-passer accepted. Nigeria, Ghana, India, China, Egypt need visa. ETA: piloted Oct 2025 (China, India, Indonesia, Mexico; G20 delegates), official launch 12 Aug 2026 at JNB; expansion to all visa-required nationals targeted Sept 2026; proposed R500 fee (R925 total with visa fee); ETA only at JNB/CPT/Lanseria. No all-Africans policy. Conference-specific facilitation: SANCB liaises with Home Affairs for delegate visas (unverified). Online traveller declaration mandatory from 1 Jul 2026. Ease score: 3', 'https://www.legit.ng/people/1719192-full-list-african-countries-citizens-visit-south-africa-a-visa-2026/', 'partial', '2026-11-04' from public.countries where name = 'South Africa' and type = 'country' on conflict (country_id, field_no) do update set value = excluded.value, source_url = excluded.source_url, confidence = excluded.confidence, verified_on = excluded.verified_on, field_group = excluded.field_group, field = excluded.field;
