insert into public.policy_frameworks (country_id, title, short_name, level, econ_sector_id, period_start, period_end, issuing_body, status, summary, source_url, data_confidence, added_by) select id, 'National Development Plan 12 (2025-2030)', 'NDP 12', 'national_plan', null, 2025, 2030, 'Ministry of Finance / National Planning', 'in_force', 'Five-year plan adopted 2025 for economic diversification. Priority sectors named: mining and energy, manufacturing, agriculture, tourism and creative industries, infrastructure, financial services. Tourism jobs +25% by 2030.', 'https://www.thestar.com.my/news/world/2025/11/07/botswana-adopts-5-year-national-development-plan-to-boost-economic-diversification', 'partial', 'rotation-map-import' from public.countries c where c.name = 'Botswana' and not exists (select 1 from public.policy_frameworks p where p.country_id = c.id and p.title = 'National Development Plan 12 (2025-2030)');
insert into public.policy_frameworks (country_id, title, short_name, level, econ_sector_id, period_start, period_end, issuing_body, status, summary, source_url, data_confidence, added_by) select id, 'Botswana MICE Strategy', 'MICE Strategy', 'strategy', 16, 2023, null, 'Botswana Tourism Organisation', 'in_preparation', 'EU-supported national MICE strategy drafted by BTO in 2023 and submitted to Cabinet in February 2025; BTO reported it as being implemented in December 2025. No public document; formal adoption unconfirmed.', 'https://www.mmegi.bw/ampArticle/116385', 'partial', 'rotation-map-import' from public.countries c where c.name = 'Botswana' and not exists (select 1 from public.policy_frameworks p where p.country_id = c.id and p.title = 'Botswana MICE Strategy');
insert into public.policy_frameworks (country_id, title, short_name, level, econ_sector_id, period_start, period_end, issuing_body, status, summary, source_url, data_confidence, added_by) select id, 'Sixth National Development Plan (NDP6) 2025/26-2029/30', 'NDP6', 'national_plan', null, 2025, 2030, 'National Planning Commission', 'in_force', 'Priority sectors: agriculture and agro-processing, manufacturing, green hydrogen, oil and gas, nuclear, mining, tourism and gaming, MSMEs, logistics, energy and digital infrastructure. Tourism arrivals target 1.8m by 2030, tourism share of GDP 1.6% to 5%.', 'https://www.namport.com.na/files/files/NDP6-Booklet.pdf', 'verified', 'rotation-map-import' from public.countries c where c.name = 'Namibia' and not exists (select 1 from public.policy_frameworks p where p.country_id = c.id and p.title = 'Sixth National Development Plan (NDP6) 2025/26-2029/30');
insert into public.policy_frameworks (country_id, title, short_name, level, econ_sector_id, period_start, period_end, issuing_body, status, summary, source_url, data_confidence, added_by) select id, 'National Spatial Tourism Master Plan 2025-2035', 'Tourism Master Plan', 'sector_policy', 16, 2025, 2035, 'Ministry of Environment, Forestry and Tourism', 'in_force', 'Ten-year tourism master plan; direct tourism jobs from 57,000 to 80,000 by 2030. The Namibia Convention Bureau (launched 16 December 2025 under NIPDB) coordinates national bids and administers the MICE Visa.', 'https://thebrief.com.na/2025/06/namibia-targets-80000-tourism-jobs-by-2030/', 'partial', 'rotation-map-import' from public.countries c where c.name = 'Namibia' and not exists (select 1 from public.policy_frameworks p where p.country_id = c.id and p.title = 'National Spatial Tourism Master Plan 2025-2035');
